function qs(e){let l=(e.qs.length?e.qs:[1,2,3,4,5,6]).map(i=>qbank.find(q=>q.id==i)).filter(Boolean);return l}
function start(id,sandbox){const e=S.exams.find(x=>x.id==id);let l=qs(e);if(e.rnd){l=[...l].sort((a,b)=>(a.d>b.d?1:-1)).map((q,i,r)=>i%2?q:r[i]);}
S.at={id,sb:!!sandbox,q:l.map(q=>({...q,o:e.rnd?q.o.map((t,i)=>[t,i]).sort(()=>Math.random()-.5):q.o.map((t,i)=>[t,i])})),ans:{},mk:{},i:0,end:Date.now()+(id=="cs301"&&!sandbox?31*60:e.dur*60)*1000,sv:"Saved",q2:0,off:false,pad:"",pd:false};
S.page="work";R();S.tm=setInterval(tick,1000)}
function tick(){if(!S.at)return;const r=Math.max(0,Math.round((S.at.end-Date.now())/1000)),t=$("#tm");if(t){t.textContent=String(Math.floor(r/60)).padStart(2,"0")+":"+String(r%60).padStart(2,"0");t.classList.toggle("low",r<300)}if(!r)finish(true)}
document.addEventListener("visibilitychange",()=>{if(S.at&&document.hidden&&S.page=="work"){inc.unshift({n:S.user.name,e:"Switched tab / left window",t:new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})});S.at.tab=(S.at.tab||0)+1}});
function work(){const a=S.at,q=a.q[a.i],e=S.exams.find(x=>x.id==a.id),n=a.q.length,ans=a.ans[q.id]||[],f=pref.f||16;
return `${a.sb?`<div class="ban wn">Sandbox preview — nothing here affects real submissions, results or statistics.</div>`:""}${a.off?`<div class="ban er">Connection lost. Answers are saved on this device and will sync automatically. The timer keeps running.</div>`:""}
<header><div class="logo"><b>EG</b><div>${e.code}<small>${e.title}</small></div></div><div style="flex:1"></div><span class="pill ${a.off?"er":"ok"}"><span class="dot ${a.off?"off":""}"></span>${a.off?"Offline":"Connected"}</span><span class="pill gr" id="sv">${a.sv}</span><span class="timer" id="tm">--:--</span><button class="btn g s" onclick="togOff()">${a.off?"Reconnect":"Simulate outage"}</button><button class="btn g s" onclick="modal(prefs())">⚙ Preferences</button><button class="btn g s" onclick="S.at.pd=!S.at.pd;R();tick()">📝 Scratchpad</button></header>
<main><div class="ws ${pref.l=="c"?"cmp":""}"><div class="card col" style="font-size:${f}px"><div class="row sp"><span class="pill in">Question ${a.i+1} of ${n}</span><span class="row"><span class="pill gr">${q.cat} · ${q.d}</span><span class="pill gr">${q.m} marks</span></span></div>
<h2 style="font-size:1.25em;line-height:1.4">${E(q.t)}</h2>${q.ty=="multi"?`<p class="mu sm">Select all that apply.</p>`:""}
${q.ty=="text"?`<textarea rows="8" placeholder="Write your answer…" oninput="setA(${q.id},this.value,1)">${E(ans[0]||"")}</textarea><p class="mu sm">Written responses are graded manually by the examiner.</p>`:q.o.map((o,j)=>`<div class="opt ${ans.includes(o[1])?"sel":""}" tabindex="0" onclick="pick(${q.id},${o[1]},'${q.ty}')"><input type="${q.ty=="mcq"?"radio":"checkbox"}" style="width:auto" ${ans.includes(o[1])?"checked":""} tabindex="-1"> ${String.fromCharCode(65+j)}. ${E(o[0])}</div>`).join("")}
<div class="row sp"><button class="btn g" ${a.i?"":"disabled"} onclick="S.at.i--;R();tick()">Previous</button><button class="btn g" onclick="S.at.mk[${q.id}]=!S.at.mk[${q.id}];R();tick()">${a.mk[q.id]?"⚑ Unmark":"⚐ Mark for review"}</button>${a.i<n-1?`<button class="btn" onclick="S.at.i++;R();tick()">Next</button>`:`<button class="btn" onclick="modal(rev())">Review & Submit</button>`}</div></div>
<div class="col side"><div class="card col"><h3>Question Navigation</h3><div class="qn">${a.q.map((x,i)=>`<button class="${a.mk[x.id]?"m":(a.ans[x.id]||[]).length&&a.ans[x.id][0]!==""?"a":""} ${i==a.i?"c":""}" onclick="S.at.i=${i};R();tick()" aria-label="Question ${i+1}">${i+1}</button>`).join("")}</div><div class="lg"><span><i style="background:var(--pr)"></i>Answered</span><span><i style="background:var(--wn)"></i>Review</span><span><i style="border:1px solid var(--mu)"></i>Open</span></div><button class="btn w" onclick="modal(rev())">Review & Submit</button></div>
${ann.length?`<div class="card" style="background:var(--soft)"><b>📣 Announcement</b><p class="sm">${E(ann[0])}</p></div>`:""}
${a.pd?`<div class="card col"><h3>Digital Scratchpad</h3><textarea rows="9" placeholder="Rough work. Never submitted." oninput="S.at.pad=this.value">${E(a.pad)}</textarea><p class="mu sm">Private to you. Kept during this attempt only.</p></div>`:""}</div></div></main>`}
function pick(id,j,ty){const a=S.at;let c=a.ans[id]||[];c=ty=="mcq"?[j]:c.includes(j)?c.filter(x=>x!=j):[...c,j];setA(id,c)}
function setA(id,v,txt){S.at.ans[id]=txt?[v]:v;S.at.sv=S.at.off?"Saved locally · will sync":"Saving…";if(!txt)R();else tick();clearTimeout(S.sv);S.sv=setTimeout(()=>{if(S.at){S.at.sv=S.at.off?"Saved locally · will sync":"All changes saved";const s=$("#sv");if(s)s.textContent=S.at.sv}},700);if(!txt)tick()}
function togOff(){S.at.off=!S.at.off;if(!S.at.off){S.at.sv="Synced";toast("Back online — answers synced")}R();tick()}
function prefs(){return `<h2>Workspace preferences</h2><p class="mu sm" style="margin:4px 0 14px">Saved on this device and applied to every exam.</p><div class="col"><label>Text size<select onchange="pref.f=+this.value;sp();R();tick()"><option value="14" ${pref.f==14?"selected":""}>Small</option><option value="16" ${!pref.f||pref.f==16?"selected":""}>Medium</option><option value="19" ${pref.f==19?"selected":""}>Large</option></select></label><label>Layout<select onchange="pref.l=this.value;sp();R();tick()"><option value="s">Question + side panel</option><option value="c" ${pref.l=="c"?"selected":""}>Compact (navigator on top)</option></select></label><label>Theme<select onchange="document.documentElement.dataset.theme=this.value"><option value="light">Light</option><option value="dark">Dark</option></select></label><button class="btn" onclick="modal()">Done</button></div>`}
function rev(){const a=S.at,an=a.q.filter(q=>(a.ans[q.id]||[]).length&&a.ans[q.id][0]!=="").length,mk=a.q.filter(q=>a.mk[q.id]).length;return `<h2>Submit your attempt?</h2><div class="grid g3" style="margin:16px 0"><div class="stat ok"><b>${an}</b>Answered</div><div class="stat"><b>${a.q.length-an}</b>Unanswered</div><div class="stat"><b style="color:var(--wn)">${mk}</b>For review</div></div><p class="mu sm">Once submitted you cannot change answers. Duplicate submissions are blocked.</p><div class="row" style="margin-top:16px"><button class="btn g" onclick="modal()">Keep working</button><button class="btn" onclick="finish()">Submit attempt</button></div>`}
function finish(auto){modal();const a=S.at;clearInterval(S.tm);S.at=null;S.page="dash";R();toast(a.sb?"Sandbox attempt discarded":auto?"Time is up — attempt finalised with accepted answers":"Submitted. Objective answers graded; results are published by your examiner.")}
